$("#downloadJobDesc").click(function () {
  // Prepare the base64 image (for demonstration, replace with your own base64 string)
  const imageBase64 = ``;
  const doc = new docx.Document({
    sections: [
      {
        headers: {
          default: new docx.Header({
            children: [
              new docx.ImageRun({
                data: imageBase64,
                transformation: {
                  width: 200,
                  height: 200,
                },
                floating: {
                  horizontalPosition: {
                    offset: 2014400,
                  },
                  verticalPosition: {
                    offset: 2014400,
                  },
                },
              }),
              // new docx.Paragraph("Header text")
            ],
          }),
        },
        footers: {
          default: new docx.Footer({
            children: [new docx.Paragraph("Footer text")],
          }),
        },
        children: [new docx.Paragraph("Hello World")],
      },
    ],
  });

  // Generate and save the DOCX file
  docx.Packer.toBlob(doc).then(function (blob) {
    saveAs(blob, "generated_document_with_header.docx");
  });
});
